<script setup lang="ts">
import InputText from 'primevue/inputtext'
import InputNumber from 'primevue/inputnumber'
import Select from 'primevue/select'
import Checkbox from 'primevue/checkbox'
import Textarea from 'primevue/textarea'
import FileUpload from 'primevue/fileupload'
import Button from 'primevue/button'

import { ref,reactive,watch,computed } from 'vue'
import Dialog from 'primevue/dialog'
import FormDatePicker from './FormDatePicker.vue'
import { Plus,Trash2,Paperclip } from 'lucide-vue-next'
import { useToast } from 'primevue/usetoast'
import { useGarage } from '../stores/garage'
import { api,allPages } from '../services/api'
import { useMechanics } from '../stores/mechanics'
import MechanicDialog from './MechanicDialog.vue'
import PaymentsEditor from './PaymentsEditor.vue'
import { categories,serviceTypes,money,today,aiFieldLabels } from '../services/types'
import type { MaintenanceAiDraft,RecordEntry,Mechanic,PaymentDraft } from '../services/types'
const visible=defineModel<boolean>('visible',{default:false}),props=defineProps<{record?:RecordEntry|null;componentKey?:string|null;subcomponentId?:string|null;aiDraft?:MaintenanceAiDraft|null}>(),emit=defineEmits<{saved:[];editAiMessage:[]}>()
const g=useGarage(),directory=useMechanics(),toast=useToast(),busy=ref(false),error=ref(''),files=ref<File[]>([]),savedId=ref<string|null>(null),attachments=ref<RecordEntry['attachments']>([])
const pricingMode=ref<'package'|'detailed'>('package')
const pricingOptions=[{value:'package',label:'Valor total fechado'},{value:'detailed',label:'Valores detalhados'}]
const form=reactive({date:today(),category:'General',serviceType:'Preventive',description:'',mileage:null as number|null,laborCost:0 as number|null,packageTotal:null as number|null,payments:[] as PaymentDraft[],workshop:'',mechanicId:null as string|null,notes:'',componentIds:[] as string[],subcomponentIds:[] as string[],primaryComponentId:null as string|null,items:[] as {name:string;quantity:number|null;unitCost:number|null}[]})
watch(visible,v=>{if(!v){mechanicVersion++;return;}error.value='';files.value=[];savedId.value=props.record?.id??null;attachments.value=props.record?.attachments??[];Object.assign(form,props.record?{...props.record,laborCost:props.record.laborCost??0,packageTotal:props.record.packageTotal??null,payments:(props.record.payments??[]).map(p=>({scope:p.scope,method:p.method,installments:p.installments,totalCharged:p.totalCharged})),componentIds:props.record.components.map(c=>c.id),subcomponentIds:props.record.subcomponents.map(s=>s.id),primaryComponentId:props.record.primaryComponentId,mechanicId:props.record.mechanicId??null,items:props.record.items.map(i=>({name:i.name,quantity:i.quantity,unitCost:i.unitCost??0}))}:{date:today(),category:({engine:'Engine',suspension:'Suspension',body:'Body',wheels:'Tires',brakes:'Brakes',battery:'Electrical',lights:'Electrical',cooling:'Cooling',exhaust:'Exhaust',transmission:'Transmission'} as Record<string,string>)[props.componentKey??'']??'General',serviceType:'Preventive',description:'',mileage:null,laborCost:0,packageTotal:null,payments:[],workshop:'',mechanicId:null,notes:'',componentIds:g.components.filter(c=>c.key===props.componentKey).map(c=>c.id),subcomponentIds:props.subcomponentId?[props.subcomponentId]:[],primaryComponentId:g.components.find(c=>c.key===props.componentKey)?.id??null,items:[]});pricingMode.value=props.record&&props.record.packageTotal==null?'detailed':'package';if(props.aiDraft&&!props.record){const d=props.aiDraft;Object.assign(form,{date:d.serviceDate??'',category:d.category??'',serviceType:d.serviceType??'',description:d.description,mileage:d.mileage,laborCost:null,packageTotal:d.totalCost,payments:[],workshop:d.workshop??'',mechanicId:null,notes:d.notes??'',componentIds:d.components.map(c=>c.id),subcomponentIds:d.components.flatMap(c=>c.subcomponents.map(s=>s.id)),primaryComponentId:d.components[0]?.id??null,items:d.items.map(i=>({name:i.name,quantity:i.quantity,unitCost:null}))});pricingMode.value='package'}previousMechanicId=form.mechanicId;loadMechanics()})
const mechanics=ref<Mechanic[]>([]),mechanicsBusy=ref(false),mechanicsError=ref(''),mechanicOpen=ref(false)
let mechanicVersion=0,previousMechanicId:string|null=null
const mechanicOptions=computed(()=>mechanics.value.map(m=>({...m,label:m.name+(m.isArchived?' · arquivado':''),disabled:m.isArchived&&m.id!==props.record?.mechanicId})))
async function loadMechanics(){
 const version=++mechanicVersion;mechanicsBusy.value=true;mechanicsError.value=''
 try{
  const rows=await allPages<Mechanic>('/mechanics')
  const existing=props.record?.mechanicId??form.mechanicId
  if(existing&&!rows.some(m=>m.id===existing))rows.push(await api<Mechanic>('/mechanics/'+existing))
  if(version===mechanicVersion&&visible.value)mechanics.value=rows
 }catch(e){if(version===mechanicVersion)mechanicsError.value=(e as Error).message}finally{if(version===mechanicVersion)mechanicsBusy.value=false}
}
watch(()=>directory.revision,()=>{if(visible.value)loadMechanics()})
function selectMechanic(id:string|null){
 const selected=mechanics.value.find(m=>m.id===id),old=mechanics.value.find(m=>m.id===previousMechanicId)
 if(selected&&(!form.workshop||form.workshop===old?.workshop))form.workshop=selected.workshop??''
 form.mechanicId=id;previousMechanicId=id
}
function mechanicSaved(m:Mechanic){mechanics.value=[...mechanics.value.filter(row=>row.id!==m.id),m];selectMechanic(m.id)}
const involved=computed(()=>g.components.filter(c=>form.componentIds.includes(c.id)))
const example=ref<string|null>(null)
const examples=[{value:'suspension',label:'Troca de amortecedores'},{value:'ignition',label:'Troca de cabos e velas'}]
watch(visible,()=>{example.value=null})
watch(()=>[...form.componentIds],()=>{
 const allowed=new Set(involved.value.flatMap(c=>c.subcomponents.map(s=>s.id)))
 form.subcomponentIds=form.subcomponentIds.filter(id=>allowed.has(id))
 if(!form.primaryComponentId||!form.componentIds.includes(form.primaryComponentId))form.primaryComponentId=form.componentIds[0]??null
})
function applyExample(){
 if(!example.value)return
 const component=g.components.find(c=>c.key===(example.value==='suspension'?'suspension':'engine'))
 if(!component)return
 const keys=example.value==='suspension'?['shock-absorbers']:['ignition-cables','spark-plugs']
 form.componentIds=[component.id];form.primaryComponentId=component.id
 form.subcomponentIds=component.subcomponents.filter(s=>keys.includes(s.key)).map(s=>s.id)
 form.category=example.value==='suspension'?'Suspension':'Engine';form.serviceType='Replacement'
 form.description=examples.find(e=>e.value===example.value)!.label
}
const partsTotal=computed(()=>form.items.reduce((sum,i)=>sum+Math.round(Number(i.quantity||0)*Number(i.unitCost||0)*100),0)/100)
const baseTotal=computed(()=>pricingMode.value==='package'?Number(form.packageTotal??0):Math.round((Number(form.laborCost||0)+partsTotal.value)*100)/100)
const interestTotal=computed(()=>form.payments.reduce((sum,p)=>sum+(p.totalCharged==null?0:Math.round((p.totalCharged-(p.scope==='Parts'?partsTotal.value:p.scope==='Labor'?Number(form.laborCost||0):Number(form.packageTotal??0)))*100)),0)/100)
const total=computed(()=>Math.round((baseTotal.value+interestTotal.value)*100)/100)
const missingAiPrices=computed(()=>!!props.aiDraft&&pricingMode.value==='detailed'&&(form.laborCost==null||form.items.some(i=>i.unitCost==null)))
const pendingPayments=computed(()=>form.payments.some(p=>p.totalCharged==null))
async function save(){if(busy.value||!g.selectedId)return;busy.value=true;error.value='';try{
 if(missingAiPrices.value)throw new Error('Informe os valores detalhados. A IA não preenche preços individuais desconhecidos.')
 if(!form.date||!form.category||!form.serviceType||!form.componentIds.length)throw new Error('Preencha a data, a categoria, o tipo e os componentes envolvidos.')
 if(form.items.some(i=>i.quantity==null))throw new Error('Informe a quantidade de cada peça. A IA não preenche quantidades desconhecidas.')
 if(pricingMode.value==='package'&&form.packageTotal==null)throw new Error('Informe o valor total cobrado pela oficina.')
 const payload={...form,packageTotal:pricingMode.value==='package'?Number(form.packageTotal):null,mileage:form.mileage==null||String(form.mileage)===''?null:Number(form.mileage),laborCost:pricingMode.value==='package'?0:Number(form.laborCost),items:form.items.map(i=>({...i,quantity:Number(i.quantity),unitCost:pricingMode.value==='package'?0:Number(i.unitCost)}))}
 const base=`/vehicles/${g.selectedId}/records`,r=await api<RecordEntry>(base+(savedId.value?'/'+savedId.value:''),{method:savedId.value?'PUT':'POST',body:JSON.stringify(payload)});savedId.value=r.id;directory.changed();emit('saved')
 while(files.value.length){const data=new FormData();data.append('file',files.value[0]!);const a=await api<RecordEntry['attachments'][number]>(base+'/'+r.id+'/attachments',{method:'POST',body:data});attachments.value.push(a);files.value.shift()}
 toast.add({severity:'success',summary:'Serviço registrado',life:3000});visible.value=false;emit('saved')
 }catch(e){error.value=(savedId.value?'O serviço está salvo. ':'')+(e as Error).message}finally{busy.value=false}}
async function removeAttachment(id:string){if(!confirm('Excluir este anexo?'))return;try{await api(`/vehicles/${g.selectedId}/records/${savedId.value}/attachments/${id}`,{method:'DELETE'});attachments.value=attachments.value.filter(a=>a.id!==id);emit('saved')}catch(e){error.value=(e as Error).message}}
</script>
<template><Dialog v-model:visible="visible" modal :header="savedId?'Editar serviço':props.aiDraft?'Revisar registro da IA':'Registrar serviço'" :style="{width:'760px'}" :breakpoints="{'800px':'95vw'}" :closable="!busy" :close-on-escape="!busy"><form class="form-grid" @submit.prevent="save"><section v-if="props.aiDraft" class="full ai-review-notice" aria-label="Sugestão da IA"><h3>Sugestão da IA · revisão obrigatória</h3><p>Nenhum serviço foi salvo. Confira as peças, o veículo e os valores antes de confirmar.</p><p v-if="props.aiDraft.missingFields.length">Informações não identificadas: {{props.aiDraft.missingFields.map(key=>aiFieldLabels[key]??key).join(', ')}}.</p><ul v-if="props.aiDraft.warnings.length"><li v-for="warning in props.aiDraft.warnings" :key="warning">{{warning}}</li></ul><Button type="button" class="text-button" @click="emit('editAiMessage')">Editar relato e gerar outra sugestão</Button></section><label v-if="!savedId" class="full" for="record-example">Sugestão de preenchimento (opcional)<Select input-id="record-example" aria-label="Sugestão de preenchimento" v-model="example" :options="examples" option-label="label" option-value="value" placeholder="Começar do zero" show-clear @change="applyExample" /><small class="form-hint">A sugestão preenche a descrição e os componentes. Informe os valores reais do seu serviço.</small></label><label class="full" for="record-description">Descrição<InputText id="record-description" v-model="form.description" required maxlength="300" placeholder="Ex.: troca de óleo e filtro do motor" /></label><label for="record-date">Data do serviço<FormDatePicker input-id="record-date" v-model="form.date" :max-date="new Date()" required /></label><label for="record-mileage">Quilometragem (opcional)<InputNumber input-id="record-mileage" v-model="form.mileage" :min="0" :max="g.selected?.mileage??10000000" :use-grouping="false" placeholder="Não informada" /></label><label for="record-category">Categoria<Select aria-label="Categoria" input-id="record-category" v-model="form.category" :options="Object.entries(categories).map(([value,label])=>({value,label}))" option-label="label" option-value="value" /></label><label for="record-serviceType">Tipo de serviço<Select aria-label="Tipo de serviço" input-id="record-serviceType" v-model="form.serviceType" :options="Object.entries(serviceTypes).map(([value,label])=>({value,label}))" option-label="label" option-value="value" /></label><fieldset class="full"><legend>Componentes envolvidos</legend><p class="form-hint">Selecione um ou mais. O custo será contado uma única vez.</p><div class="component-checks"><label v-for="c in g.components" :key="c.id" :for="'record-component-'+c.id"><Checkbox :input-id="'record-component-'+c.id" v-model="form.componentIds" :value="c.id" />{{c.name}}</label></div></fieldset><label v-if="involved.length" class="full" for="record-primary">Componente principal<Select input-id="record-primary" aria-label="Componente principal" v-model="form.primaryComponentId" :options="involved" option-label="name" option-value="id" required /></label><fieldset v-for="c in involved" :key="c.id" class="full subcomponent-fields"><legend>Subcomponentes · {{c.name}} (opcional)</legend><div class="component-checks"><label v-for="s in c.subcomponents" :key="s.id" :for="'record-sub-'+s.id"><Checkbox :input-id="'record-sub-'+s.id" v-model="form.subcomponentIds" :value="s.id" />{{s.name}}</label></div></fieldset><div class="full record-pricing"><label for="record-pricing-mode">Como deseja informar o valor?<Select input-id="record-pricing-mode" aria-label="Como deseja informar o valor?" v-model="pricingMode" :options="pricingOptions" option-label="label" option-value="value" /></label><p id="record-pricing-hint" class="form-hint">{{pricingMode==='package'?'A oficina cobrou um valor único? Registre o total e tudo o que foi feito, sem dividir o preço por peça ou serviço.':'Informe os preços das peças e da mão de obra. O total será calculado automaticamente.'}}</p><label v-if="pricingMode==='package'" for="record-package-total">Valor total cobrado (R$)<InputNumber input-id="record-package-total" v-model="form.packageTotal" :min="0" :max="100000000" :max-fraction-digits="2" :use-grouping="false" locale="pt-BR" placeholder="Ex.: 1000" aria-describedby="record-pricing-hint" required /></label><small v-if="pricingMode==='package'" class="form-hint">Inclui peças e mão de obra. Esse valor será contado uma única vez, mesmo com vários componentes selecionados.</small></div><div class="full form-section"><div class="section-header"><h3>Peças substituídas</h3><Button type="button" class="text-button" @click="form.items.push({name:'',quantity:1,unitCost:0})"><Plus :size="16"/>Adicionar peça</Button></div><div v-for="(item,index) in form.items" :key="index" class="item-fields" :class="{'item-fields--package':pricingMode==='package'}"><label :for="'item-name-'+index">Peça<InputText :id="'item-name-'+index" v-model="item.name" required maxlength="160" /></label><label :for="'item-quantity-'+index">Qtd.<InputNumber :input-id="'item-quantity-'+index" v-model="item.quantity" :min="1" :max="10000" :use-grouping="false" required /></label><label v-if="pricingMode==='detailed'" :for="'item-cost-'+index">Valor unitário (R$)<InputNumber :input-id="'item-cost-'+index" v-model="item.unitCost" :min="0" :max="100000000" :max-fraction-digits="2" :use-grouping="false" locale="pt-BR" required /></label><Button type="button" class="icon-button" :aria-label="'Remover peça '+(index+1)" @click="form.items.splice(index,1)"><Trash2 :size="17"/></Button></div><p v-if="!form.items.length" class="muted">Nenhuma peça adicionada.</p></div><label v-if="pricingMode==='detailed'" for="record-labor">Mão de obra (R$)<InputNumber input-id="record-labor" v-model="form.laborCost" :min="0" :max="100000000" :max-fraction-digits="2" :use-grouping="false" locale="pt-BR" required /></label><PaymentsEditor v-model="form.payments" :parts="partsTotal" :labor="Number(form.laborCost||0)" :package-total="form.packageTotal" :package-mode="pricingMode==='package'" /><div class="full record-mechanic-field"><label for="record-mechanic">Mecânico responsável (opcional)<Select input-id="record-mechanic" aria-label="Mecânico responsável" v-model="form.mechanicId" :options="mechanicOptions" option-label="label" option-value="id" option-disabled="disabled" filter show-clear :loading="mechanicsBusy" :disabled="mechanicsBusy" placeholder="Selecionar um contato da agenda" @change="selectMechanic($event.value)" /></label><Button type="button" class="text-button" @click="mechanicOpen=true"><Plus :size="15"/>Cadastrar mecânico sem sair do serviço</Button><p v-if="mechanicsError" class="form-error" role="alert">{{mechanicsError}} <Button type="button" class="text-button" @click="loadMechanics">Tentar novamente</Button></p><small class="form-hint">Você também pode informar a oficina livremente abaixo.</small></div><label for="record-workshop">Oficina ou responsável<InputText id="record-workshop" v-model="form.workshop" maxlength="200" /></label><label class="full" for="record-notes">Observações<Textarea id="record-notes" v-model="form.notes" rows="3" maxlength="4000" auto-resize /></label><label class="full upload-label"><span><Paperclip :size="17"/>Fotos e notas fiscais</span><FileUpload name="attachments" accept="image/png,image/jpeg,image/webp,application/pdf" multiple :max-file-size="8388608" :file-limit="20" custom-upload :show-upload-button="false" :show-cancel-button="false" choose-label="Selecionar arquivos" @select="files=$event.files" @remove="files=files.filter(f=>f!==$event.file)" ><template #empty><p class="muted">Arraste suas fotos e notas fiscais para cá.</p></template></FileUpload><small>PNG, JPEG, WebP ou PDF. Até 8 MB por arquivo; até 20 anexos.</small></label><div v-if="files.length" class="full muted">{{files.map(f=>f.name).join(', ')}}</div><div v-for="a in attachments" :key="a.id" class="full attachment-row"><a :href="a.url" target="_blank" rel="noopener">{{a.fileName}}</a><Button type="button" class="icon-button" :aria-label="'Excluir anexo '+a.fileName" @click="removeAttachment(a.id)"><Trash2 :size="16"/></Button></div><p v-if="error" class="full form-error" role="alert">{{error}}</p><div class="full form-actions"><span>{{pendingPayments?'Total conhecido':'Total do serviço'}}<strong>{{(pricingMode==='package'&&form.packageTotal==null)||missingAiPrices?'A informar':money(total)}}</strong><small v-if="interestTotal>0">Inclui {{money(interestTotal)}} de juros</small><small v-if="pendingPayments">Juros pendentes de informação</small></span><Button type="button" class="button" :disabled="busy" @click="visible=false">Cancelar</Button><Button type="submit" class="button primary" :disabled="busy||!form.componentIds.length">{{busy?'Salvando…':props.aiDraft?'Confirmar e salvar serviço':'Salvar serviço'}}</Button></div></form></Dialog><MechanicDialog v-model:visible="mechanicOpen" @saved="mechanicSaved" /></template>
